'use strict';
(()=>{const picker=document.getElementById('datePicker'),toggle=document.getElementById('dateToggle'),popover=document.getElementById('datePopover'),month=document.getElementById('month'),grid=document.getElementById('calendar'),status=document.getElementById('monthStatus');const requested=new URLSearchParams(location.search).get('date')||'2026-10-27';const valid=/^\d{4}-\d{2}-\d{2}$/.test(requested);month.value=valid?requested.slice(0,7):'2026-10';toggle.textContent=(valid?requested:'选择研究日期')+' ▾';
function close(restore=false){popover.hidden=true;toggle.setAttribute('aria-expanded','false');if(restore)toggle.focus()}
function render(){grid.replaceChildren();if(!/^\d{4}-\d{2}$/.test(month.value)){status.textContent='月份无效';return}const [y,m]=month.value.split('-').map(Number);if(m<1||m>12){status.textContent='月份无效';return}status.textContent=month.value+' · 按实际研究日归档';for(const x of ['一','二','三','四','五','六','日']){const e=document.createElement('span');e.textContent=x;grid.append(e)}for(let n=0;n<(new Date(y,m-1,1).getDay()+6)%7;n++)grid.append(document.createElement('span'));for(let n=1;n<=new Date(y,m,0).getDate();n++){const date=month.value+'-'+String(n).padStart(2,'0'),b=document.createElement('button');b.type='button';b.className='day'+(date==='2026-10-27'?' archived':'');b.textContent=String(n);b.dataset.date=date;b.setAttribute('aria-label',date+(date==='2026-10-27'?' 已归档':' 未归档'));if(date===requested)b.setAttribute('aria-current','date');b.onclick=()=>{close();location.href='daily.html?date='+date};b.onkeydown=e=>{const ds=[...grid.querySelectorAll('button')],i=ds.indexOf(b);let to;if(e.key==='ArrowRight')to=i+1;else if(e.key==='ArrowLeft')to=i-1;else if(e.key==='ArrowDown')to=i+7;else if(e.key==='ArrowUp')to=i-7;else if(e.key==='Home')to=0;else if(e.key==='End')to=ds.length-1;if(to!==undefined){e.preventDefault();ds[Math.max(0,Math.min(ds.length-1,to))].focus()}};grid.append(b)}}
toggle.onclick=()=>{if(!popover.hidden){close();return}render();popover.hidden=false;toggle.setAttribute('aria-expanded','true');(grid.querySelector('[aria-current="date"]')||month).focus()};month.onchange=render;document.addEventListener('click',e=>{if(!popover.hidden&&!picker.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!popover.hidden){e.preventDefault();close(true)}});picker.addEventListener('focusout',e=>{if(e.relatedTarget&&!picker.contains(e.relatedTarget))close()});render();})();
